export function MeridianWordmark({ height = 24, className }: { height?: number; className?: string }) {
  return (
    <svg
      className={className ? `meridian-wordmark ${className}` : 'meridian-wordmark'}
      viewBox={WORDMARK_VIEWBOX}
      height={height}
      width={Math.round((height * 1835) / 372)}
      aria-hidden="true"
      focusable="false"
    >
      <path d={WORDMARK_PATH} fill="currentColor" fillRule="evenodd" />
    </svg>
  );
}

/** The mark and the wordmark side by side, the name kept for whoever cannot see them. */
export function MeridianLockup({ height = 24, label = 'Meridian', className }: { height?: number; label?: string; className?: string }) {
  return (
    <span className={className ? `meridian-lockup ${className}` : 'meridian-lockup'}>
      <MeridianMark height={height} />
      <MeridianWordmark height={Math.round(height * 0.86)} />
      <span className="sr-only">{label}</span>
    </span>
  );
}

/* The camel (Rami, 2026-09-30; made the one mark 2026-10-08): the company's
   only mark, one flat path from design-assets/camel-mark-2026-09-30/
   nomad-camel.svg (= public/brand/nomad-camel.svg). Inline, in currentColor,
   so the bar draws it charcoal on white and the footer pearl on black from
   the same path, with no request and no second file to keep in step. Never
   used for MeridianOS: MeridianOS is its own product and is set in type until its icon lands. */
const CAMEL_VIEWBOX = '416.9 409.9 2371.5 1398.2';
const CAMEL_PATH =
  'M462.49 1762.50 C466.31 1640.02 530.14 1513.94 575.92 1426.92 C700.37 1190.37 868.89 959.99 1067.65 780.32 C1174.04 684.15 1307.45 593.86 1457.41 632.97 C1672.41 689.04 1731.83 1074.70 1972.28 1053.36 C2107.30 1041.38 2192.37 906.20 2205.10 782.32 C2217.32 663.44 2179.53 538.74 2317.71 477.48 C2424.51 430.14 2551.09 467.24 2650.65 511.83 C2683.26 526.44 2764.85 554.67 2737.15 604.92 C2722.24 631.96 2655.23 625.77 2627.67 630.02 C2563.60 639.89 2503.32 670.39 2460.33 719.57 C2380.37 811.02 2362.91 943.28 2327.53 1055.41 C2257.56 1277.16 2076.95 1653.45 1832.43 1719.85 C1711.76 1752.62 1650.55 1656.50 1592.16 1569.53 C1519.45 1461.24 1433.70 1352.09 1309.27 1301.07 C1065.71 1201.23 775.74 1425.21 618.15 1592.28 C570.76 1642.52 529.07 1702.41 462.49 1762.50 Z';

/** The Nomad camel at a height; its width follows the mark's own proportion. */
export function CamelMark({ height = 18, className }: { height?: number; className?: string }) {
  return (
    <svg
      className={className ? `camel ${className}` : 'camel'}
      viewBox={CAMEL_VIEWBOX}
      height={height}
      width={Math.round((height * 2371.5) / 1398.2)}
      aria-hidden="true"
      focusable="false"
    >
      <path fill="currentColor" d={CAMEL_PATH} />
    </svg>
  );
}

/* The Meridian mark (Rami, 2026-10-10): a globe with a line drawn across it,
   a meridian arcing over a planet. Two shapes of true circular arcs, traced
   from Rami's master in design-assets/meridian-arc-2026-10-10 (build.cjs
   regenerates meridian-mark-paths.json, the source of these); cropped to the
   ink and inline in currentColor like the camel. Meridian's own mark, never
   Nomad's. */
export const MERIDIAN_PATHS = [
  'M245.34 727.14A422.95 422.95 0 1 1 1073.23 687.91A666.70 666.70 0 0 0 245.34 727.14Z',
  'M265.95 788.31A624.95 624.95 0 0 1 853.25 629.10A484.10 484.10 0 0 0 416.08 971.87A422.95 422.95 0 0 1 265.95 788.31Z',
];
const MERIDIAN_VIEWBOX = '228.33 196.11 853.9 779.89';

/** The Meridian mark at a height; its width follows the mark's proportion. */
export function MeridianMark({ height = 64, className }: { height?: number; className?: string }) {
  return (
    <svg
      className={className ? `meridian-mark ${className}` : 'meridian-mark'}
      viewBox={MERIDIAN_VIEWBOX}
      height={height}
      width={Math.round((height * 853.9) / 779.89)}
      aria-hidden="true"
      focusable="false"
    >
      {MERIDIAN_PATHS.map((d) => (
        <path key={d} d={d} fill="currentColor" />
      ))}
    </svg>
  );
}

/** Apple's "Learn more ›": a quiet link whose chevron is the affordance. */
export function More({ href, children, className }: { href: string; children: ReactNode; className?: string }) {
  return (
    <a className={className ? `more ${className}` : 'more'} href={href}>
      <span>{children}</span>
      <Sym name="caretRight" size={12} variant="Linear" />
    </a>
  );
}

/** A plan line: `**x**` is bold, the rest plain. */
export function Rich({ text }: { text: string }) {
  const parts = text.split(/\*\*(.+?)\*\*/g);
  return <>{parts.map((p, i) => (i % 2 ? <b key={i}>{p}</b> : p))}</>;
}

export function Checks({ lead, lines }: { lead?: string; lines: string[] }) {
  return (
    <ul className="checks">
      {lead && <li className="checks-lead">{lead}</li>}
      {lines.map((l) => (
        <li key={l}>
          <Sym name="check" size={16} className="checks-mark" />
          <span>
            <Rich text={l} />
          </span>
        </li>
      ))}
    </ul>
  );
}

const ICON: Record<ProductKey, string> = {
  ax: '/assets/icons/meridian.webp?v=20261010d',
  polaris: '/assets/icons/polaris.webp?v=20261018s',
  reach: '/assets/icons/reach.webp',
  drift: '/assets/icons/drift.webp?v=20261010a',
  citadel: '/assets/icons/citadel.webp?v=20261010a',
  /* Nomad Office's own icon, the four-colour cube on a white squircle (Rami, 2026-10-16), traced in
     nomad-office (tools/trace-office-mark.py, office-bundle-icon.cjs). Only Nomad Office wears it;
     each app keeps its own. */
  office: '/assets/icons/office.webp?v=20261016b',
  folio: '/assets/icons/folio.webp',
  grids: '/assets/icons/grids.webp',
  expo: '/assets/icons/expo.webp',
  markup: '/assets/icons/markup.webp',
};

/** A product's mark at a size: its app icon (MeridianOS: design-assets/meridian-mark-2026-10-09). */
export function ProductMark({ product, size = 64, label }: { product: ProductKey; size?: number; label?: string }) {
  const style = { '--s': `${size}px` } as CSSProperties;
  const alt = label ?? '';
  return <img className="icon" src={ICON[product]} alt={alt} width={size} height={size} style={style} />;
}

export { Sym };
